FILE: app/src/pose-mode.ts
```ts
import type { AnimationGroup } from "@babylonjs/lite";
import { removeAnimationGroup, addAnimationGroup, playAnimation } from "@babylonjs/lite";

export function freezeForPosing(group: AnimationGroup): () => void {
    const manager = group._animationManager;
    if (manager) {
        removeAnimationGroup(manager, group);
    }

    return () => {
        if (manager) {
            addAnimationGroup(manager, group);
        }
        playAnimation(group);
    };
}
```

I detached the group from its manager to freeze it (this stops all writing for both glTF and property groups, since a paused glTF group would otherwise keep re-applying its pose every frame per note 27), and the returned `resume` re-attaches it and calls `playAnimation` so it picks up from the preserved `currentTime` at its own `speedRatio`. I'm slightly unsure whether `removeAnimationGroup` could alter the group's `isPlaying` flag as a side effect, but the notes and API suggest it only manages the manager's task list, so `playAnimation` on resume should handle any residual state.
